// shader_text.h: THE RENDERER'S SHADERS, BUILT INTO THE EDITOR (the owner's "baked in", 2026-11-19, Bishop's order). The pinned AvPx's shaders\*.vsh / *.psh and the .fxh they
// include are text in the editor itself (shader_text_data.cpp, GENERATED by tools/make-shader-text.js), so the editor needs no shaders folder anywhere: a DataFolder of Rebellion's
// files only works (a Steam install ships none), and the shaders always match the renderer they are compiled with. The editor hands ShaderText_Find to the renderer at start-up
// (R_SetShaderTextSource, avpx renderer.h): the same compile in its in-memory form, the same entry, profile and flags, and no file is read; one it lacks fails as a missing file
// does. Nothing is shipped: no shaders folder in the zip or in Tools, and no DataFolder fallback. Written 2026-11-19 by Melanikus (Drake) for AVP_OpenInteng.
// AVP_OpenInteng's own code: see License.txt, "AVP_OpenInteng's own code".
#pragma once

#include <stddef.h>

namespace host
{
	struct ShaderTextEntry
	{
		char const *name;     // as the renderer asks for it: "shadowBlur.vsh", or an #include's "lightShapes.fxh"
		char const *text;     // its text (no ending zero: length says how much)
		size_t length;
	};

	// The generated table (shader_text_data.cpp)
	extern ShaderTextEntry const kShaderTexts[];
	extern size_t const kShaderTextCount;

	// The renderer's source (R_ShaderTextSource): the text of <name>, its name compared without case as Windows finds a file; false for one it lacks. Every ask is counted.
	bool ShaderText_Find(char const *name, char const **text, size_t *length);

	// The asks so far: served from the table, and asked but not in it (the state line's "shaders")
	size_t ShaderText_Served();
	size_t ShaderText_Missing();
}
